{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "Several systematic reviews and meta-analyses on diabetes and COVID19 prognosis have observed an approximately two- to threefold increased risk of mortality due to COVID-19 for people with diabetes compared with people without diabetes [6 - 14]. However, diabetes is a complex and heterogeneous disease and recent studies have found that there are differences in associations of specific phenotypes of diabetes with comorbidities and complications [15]. Regarding COVID-19, phenotypes related to more severe forms of diabetes, such as uncontrolled blood glucose, the presence of diabetes-related complications, a higher BMI, elevated biomarkers for liver damage and inflammation, are linked to early death, endotracheal intubations or admission to intensive care units (ICUs) [16 - 18]. However, some of the findings are still conflicting, imprecisely estimated or affected by risk of bias, such as confounding.",
      "reason": "The manuscript describes existing knowledge (risk of mortality in diabetes; links between severe diabetes phenotypes and COVID-19 outcomes) and key uncertainties/limitations (conflicting findings, imprecision, and confounding/risk of bias)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "To provide the best available evidence for the identification of risk phenotypes of diabetes in association with COVID-19 severity and death, a systematic review and meta-analysis is needed that summarises the findings, reveals more robust estimates, considers risk of bias and evaluates the certainty of evidence.",
      "reason": "It explicitly explains the need for conducting the review in terms of synthesizing evidence, improving estimate robustness, addressing risk of bias, and assessing certainty."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "Several systematic reviews and meta-analyses on diabetes and COVID19 prognosis have observed an approximately two- to threefold increased risk of mortality due to COVID-19 for people with diabetes compared with people without diabetes [6 - 14]. However, diabetes is a complex and heterogeneous disease and recent studies have found that there are differences in associations of specific phenotypes of diabetes with comorbidities and complications [15]. Regarding COVID-19, phenotypes related to more severe forms of diabetes, such as uncontrolled blood glucose, the presence of diabetes-related complications, a higher BMI, elevated biomarkers for liver damage and inflammation, are linked to early death, endotracheal intubations or admission to intensive care units (ICUs) [16 - 18]. However, some of the findings are still conflicting, imprecisely estimated or affected by risk of bias, such as confounding.",
      "reason": "The rationale compares with existing systematic reviews/meta-analyses and explains why a current review is needed based on limitations of prior evidence (conflicting/uncertain/imprecise results)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "callout_0",
      "quote": null,
      "reason": "This is an observational prognosis/associations review; no intervention mechanism of action is described in the provided evidence."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "callout_0",
      "quote": null,
      "reason": "No complex intervention or delivery context is described in the provided evidence, so a logic model is not applicable."
    }
  ],
  "confidence": 74
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Aims/hypothesis Diabetes has been identified as a risk factor for poor prognosis of coronavirus disease-2019 (COVID-19). The aim of this study is to identify high-risk phenotypes of diabetes associated with COVID-19 severity and death.",
      "reason": "The abstract explicitly states the study aim/objective (identify high-risk diabetes phenotypes associated with COVID-19 severity and death)."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "Methods This is the first edition of a living systematic review and meta-analysis on observational studies investigating phenotypes in individuals with diabetes and COVID-19-related death and severity.",
      "reason": "The review is a meta-analysis of observational studies assessing associations/phenotypes, not an intervention effects review; therefore planned PICO-style comparisons are not applicable."
    }
  ],
  "confidence": 78
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "We included studies of any design that reported risk estimates (HR, RR or OR with 95% CI) for associations between phenotypes (general characteristics of individuals, diabetesspecific characteristics, presence of diabetes-related complications or underlying comorbidities, and laboratory parameters) and death and severity of COVID-19 in individuals with diabetes and WHO-defined confirmed SARS-CoV-2 infection [20]. Severity of COVID-19 was defined as a composite endpoint, including death, endotracheal intubation for mechanical ventilation, acute respiratory distress syndrome, septic shock, ICU admission, multiple organ dysfunction or failure, or hospital admission.",
      "reason": "The evidence specifies key study-characteristic components (population: diabetes + confirmed SARS‑CoV‑2; eligible study designs: any design reporting HR/RR/OR with 95% CI; and an explicit definition of the severity outcome/composite endpoint). However, it does not clearly specify any required follow-up duration/timepoint for inclusion."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Studies without primary clinical data (including modelling studies), editorials, letters, commentaries, reviews, articles not in English and guidelines were excluded.",
      "reason": "The report-characteristics criteria are partially specified (language: not in English; and publication/report types such as editorials/letters/reviews/guidelines are excluded). The evidence provided does not specify eligibility criteria for dissemination year or for publication status (e.g., unpublished vs published) as required by this element."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided evidence does not distinguish exclusion based on whether outcomes were (a) not measured versus (b) measured but outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "For similar exposures (with similar reference groups [e.g., men vs women; obese vs normal weight; use of insulin: yes vs no; pre-existing comorbidities: yes vs no]), meta-analyses were conducted separately for the two outcomes: death and severity.",
      "reason": "The evidence specifies synthesis grouping in terms of exposure comparisons (e.g., men vs women; obese vs normal weight; insulin yes vs no) and that meta-analyses were conducted separately for the two outcomes (death vs severity). However, it does not explicitly link these groups to the specific comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "If studies on the same cohort/data were identified, we selected the study with the largest number of cases. Studies with mixed populations (including individuals without diabetes or without COVID-19) were excluded [21 - 23].",
      "reason": "Rationales for notable eligibility restrictions are provided, including selecting the largest cohort when multiple reports use the same data and excluding mixed populations that include people without diabetes or without COVID-19."
    }
  ],
  "confidence": 64
}

